"""
Fuzzer harness generation. Creates libFuzzer-compatible harnesses
for functions identified during decompilation. Also wraps AFL++.
"""

import logging
import os
from typing import Dict, List, Optional

from config import CORPUS_DIR

_log = logging.getLogger(__name__)

LIBFUZZER_TEMPLATE = '''#include <stdint.h>
#include <stddef.h>
#include <string.h>

// Fuzz target: {target_func}
// Generated by BinMind

extern int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {{
    // TODO: map input bytes to function parameters
    // Match the calling convention of {target_func}

    if (size < {min_size}) return 0;

    {param_prep}

    // Call the target
    {call_target}

    return 0;
}}
'''


def generate_libfuzzer_harness(func_name: str, param_count: int = 1,
                               min_input_size: int = 16) -> str:
    """
    Generate a libFuzzer harness for a single target function.
    """
    params = []
    call_args = []

    for i in range(param_count):
        param_name = f'p{i}'
        params.append(f'    int {param_name} = *(int*)(data + {i * 4});')
        call_args.append(param_name)

    prep = '\n'.join(params) if params else '    /* no params */'
    call = f'{func_name}({", ".join(call_args)});'

    return LIBFUZZER_TEMPLATE.format(
        target_func=func_name,
        min_size=min_input_size,
        param_prep=prep,
        call_target=call,
    )


def setup_fuzzing_workspace(binary_path: str) -> Dict:
    """
    Prepare a workspace for fuzzing:
    - Create corpus directory
    - Generate seed inputs
    - Write a Makefile for libFuzzer
    """
    binary_dir = os.path.dirname(os.path.abspath(binary_path))
    binary_name = os.path.splitext(os.path.basename(binary_path))[0]
    workspace = os.path.join(CORPUS_DIR, binary_name)

    os.makedirs(workspace, exist_ok=True)

    # write a tiny seed corpus
    seed_path = os.path.join(workspace, 'seed.bin')
    with open(seed_path, 'wb') as f:
        f.write(b'\x00' * 64)
        f.write(b'\xff' * 64)
        f.write(b'AAAA\x00')
        f.write(b'%s%s%s%s')

    makefile = os.path.join(workspace, 'Makefile')
    with open(makefile, 'w', encoding='utf-8') as f:
        f.write(f'''# Auto-generated fuzzing Makefile for {binary_name}
CXX ?= clang++
CXXFLAGS += -g -O1 -fsanitize=fuzzer,address

harness: harness.cpp
\t$(CXX) $(CXXFLAGS) -o harness harness.cpp

run: harness
\t./harness -max_total_time=300 {workspace}/

clean:
\trm -f harness *.o
''')

    return {'workspace': workspace, 'seed': seed_path, 'makefile': makefile}
